// ===== lib/detail/charset.hpp =====
// lib/detail/charset.hpp — explicit ASCII character class tables.
//
// Private header: classification uses ASCII code ranges only
// (locale-sensitive std::isalnum can misread lead bytes of multi-byte
// letters such as 'é', so every range is hand-written here).
namespace cpptoml::detail::charset {

/// Whitespace: space and tab only (newlines are layered separately).
inline bool is_ws(char c) { return c == ' ' || c == '\t'; }

/// 0-9.
inline bool is_digit(char c) { return c >= '0' && c <= '9'; }

/// 0-9 a-f A-F (\u/\U hex digits; among radix prefixes a-f only follows
/// 0x).
inline bool is_hex_digit(char c) {
    return is_digit(c) || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F');
}

inline int hex_value(char c) {
    if (is_digit(c)) return c - '0';
    if (c >= 'a' && c <= 'f') return c - 'a' + 10;
    return c - 'A' + 10;
}

/// Bare key characters: A-Z a-z 0-9 _ - (TOML 1.0 allows ASCII only; any
/// non-ASCII byte is a hard error).
inline bool is_bare_key_char(char c) {
    return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') ||
           (c >= '0' && c <= '9') || c == '_' || c == '-';
}

/// Digits valid for the radix (uppercase is accepted after 0x: both 0x1F
/// and 0x1f parse).
inline bool is_radix_digit(char c, int base) {
    switch (base) {
        case 16: return is_hex_digit(c);
        case 8:  return c >= '0' && c <= '7';
        case 2:  return c == '0' || c == '1';
        default: return is_digit(c);
    }
}

/// Radix digit to value (hex maps a-f; octal/binary use 0-7).
inline unsigned radix_value(char c, int base) {
    if (base == 16) return static_cast<unsigned>(hex_value(c));
    return static_cast<unsigned>(c - '0');
}

}  // namespace cpptoml::detail::charset

// ===== lib/detail/scanner.hpp =====
// lib/detail/scanner.hpp — lexical cursor: line/column tracking and
// single-character helpers.
//
// Private header: shared by parser.cpp and the other detail headers, never
// exposed in include/. Parse failures propagate by throwing parse_abort,
// which parse() catches at the top and converts into std::expected.
namespace cpptoml::detail {

struct scanner;

/// Parse exception: carries the offending position and message; parse()
/// catches it and packs it into parse_error.
struct parse_abort {
    std::size_t line = 0;
    std::size_t col = 0;
    std::string msg;
};

/// Throw at the scanner's current position.
[[noreturn]] void fail(const scanner& s, std::string msg);

/// Throw with a precomputed position (pre-scan / document-level errors).
[[noreturn]] void fail_at(std::size_t line, std::size_t col, std::string msg);

struct scanner {
    std::string_view src;
    std::size_t pos = 0;
    std::size_t line = 1;
    std::size_t col = 1;

    explicit scanner(std::string_view text) : src(text) {}

    bool eof() const { return pos >= src.size(); }
    char peek() const { return pos < src.size() ? src[pos] : '\0'; }
    char peek_at(std::size_t ahead) const {
        return pos + ahead < src.size() ? src[pos + ahead] : '\0';
    }

    void bump() {
        if (eof()) return;
        const char c = src[pos++];
        if (c == '\n') {
            ++line;
            col = 1;
        } else if (c != '\r') {
            ++col;
        }
    }

    void bump_n(std::size_t n) {
        while (n-- > 0) bump();
    }

    /// Longest run of the same character from the current position.
    std::size_t run_length(char c) const {
        std::size_t n = 0;
        while (pos + n < src.size() && src[pos + n] == c) ++n;
        return n;
    }

    /// Newline: LF, or a properly paired CRLF (pre-scan rules out lone CR).
    bool at_newline() const {
        return peek() == '\n' || (peek() == '\r' && peek_at(1) == '\n');
    }

    void bump_newline() {
        if (peek() == '\n') { bump(); return; }  // LF
        bump();                                  // CR
        if (peek() == '\n') bump();              // CRLF finishes with LF
    }

    void skip_spaces() {
        while (!eof() && (peek() == ' ' || peek() == '\t')) bump();
    }
};

inline void fail(const scanner& s, std::string msg) {
    throw parse_abort{s.line, s.col, std::move(msg)};
}

inline void fail_at(std::size_t line, std::size_t col, std::string msg) {
    throw parse_abort{line, col, std::move(msg)};
}

/// Consume a comment up to (not including) the newline; no-op if absent.
inline void skip_comment(scanner& s) {
    while (!s.eof() && s.peek() != '\n') s.bump();
}

/// Skip any mix of spaces, comments and newlines (arrays only; entries may
/// be interleaved freely).
inline void skip_ws_comments_lines(scanner& s) {
    for (;;) {
        s.skip_spaces();
        if (s.eof()) return;
        if (s.peek() == '#') { skip_comment(s); continue; }
        if (s.at_newline()) { s.bump_newline(); continue; }
        return;
    }
}

/// Byte offset → (line, column); matches scanner counting (LF breaks the
/// line, CR never counts as a column).
inline std::pair<std::size_t, std::size_t> line_col_of(std::string_view src, std::size_t off) {
    std::size_t line = 1, col = 1;
    for (std::size_t i = 0; i < off && i < src.size(); ++i) {
        const char c = src[i];
        if (c == '\n') { ++line; col = 1; }
        else if (c != '\r') ++col;
    }
    return {line, col};
}

}  // namespace cpptoml::detail

// ===== lib/detail/rfc3339.hpp =====
// lib/detail/rfc3339.hpp — syntax and range scan of TOML 1.0 datetime
// tokens.
//
// One cursor pass plus a concrete failure reason; throws nothing and builds
// no messages (parser.cpp composes them). Grammar = full-date [Tt/SP time]
// or a bare time:
//   * full-date: 4-digit year, month 01-12, day 01..end of that month
//     (February per leap year);
//   * time: exact two-digit widths, hour 00-23, minute 00-59, second 00-60
//     (leap second); the second is mandatory (plain 17:45 and T17:45 are
//     both rejected); after '.' at least one digit is required (no comma
//     fractions);
//   * offset: Z|z or ±HH:MM (hour 00-24, minute 00-59);
//   * local time and local date never take an offset;
//   * the single-space separator only counts when a digit follows the
//     space, otherwise it is trailing whitespace.
namespace cpptoml::detail::rfc {

/// Scan result: ok = success (s advanced, raw holds the whole token); on
/// failure reason tells why.
struct scan_out {
    bool ok = false;
    std::string raw;
    const char* reason = nullptr;
};

/// Read-only look-ahead: does the current word start like a date (yyyy-)
/// or a time (hh:)?
/// Once the look-ahead hits, the value commits to the datetime path: any
/// later failure is an error, never a fallback to number scanning.
inline bool looks_like_datetime(const scanner& s) {
    const auto digit_at = [&](std::size_t i) {
        const char c = s.peek_at(i);
        return c >= '0' && c <= '9';
    };
    if (digit_at(0) && digit_at(1) && digit_at(2) && digit_at(3) && s.peek_at(4) == '-') {
        return true;
    }
    return digit_at(0) && digit_at(1) && s.peek_at(2) == ':';
}

namespace {

inline bool is_leap_year(int y) { return (y % 4 == 0 && y % 100 != 0) || y % 400 == 0; }

inline int days_in_month(int y, int m) {
    static constexpr int kDays[13] = {0, 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
    if (m == 2 && is_leap_year(y)) return 29;
    return kDays[m];
}

struct pieces {
    bool ok = false;
    const char* reason = nullptr;
};

/// Two digits; leaves the cursor untouched on failure.
inline bool take2(scanner& s, int& out) {
    const char a = s.peek();
    const char b = s.peek_at(1);
    if (a < '0' || a > '9' || b < '0' || b > '9') return false;
    out = (a - '0') * 10 + (b - '0');
    s.bump();
    s.bump();
    return true;
}

/// partial-time: hh:mm:ss[.frac] (on success the cursor sits past both).
inline pieces take_time(scanner& s) {
    pieces p;
    int hour = 0, minute = 0, second = 0;
    if (!take2(s, hour)) return {false, "小时须为两位数字"};
    if (s.peek() != ':') return {false, "小时后缺少 ':'"};
    s.bump();
    if (!take2(s, minute)) return {false, "分钟须为两位数字"};
    if (minute > 59) return {false, "分钟超出 00-59 范围"};
    if (s.peek() != ':') return {false, "分钟后缺少 ':'（秒不能省略）"};
    s.bump();
    if (!take2(s, second)) return {false, "秒须为两位数字"};
    if (hour > 23) return {false, "小时超出 00-23 范围"};
    if (second > 60) return {false, "秒超出 00-60 范围（含闰秒）"};
    // Optional fraction: '.' must be followed by >= 1 digit (time-secfrac)
    if (s.peek() == '.') {
        s.bump();
        std::size_t frac = 0;
        while (!s.eof() && s.peek() >= '0' && s.peek() <= '9') {
            s.bump();
            ++frac;
        }
        if (frac == 0) return {false, "小数点后必须有数字"};
    }
    p.ok = true;
    return p;
}

/// Z|z or ±HH:MM; a missing tail or a one-digit minute is rejected.
inline pieces take_offset(scanner& s) {
    pieces p;
    if (const char z = s.peek(); z == 'Z' || z == 'z') {
        s.bump();
        p.ok = true;
        return p;
    }
    if (s.peek() != '+' && s.peek() != '-') return {false, "时间后存在无关内容"};
    s.bump();
    int oh = 0, om = 0;
    if (!take2(s, oh)) return {false, "偏移小时须为两位数字"};
    if (s.peek() != ':') return {false, "偏移小时后缺少 ':'"};
    s.bump();
    if (!take2(s, om)) return {false, "偏移分钟须为两位数字"};
    if (oh > 24) return {false, "偏移小时超出 00-24 范围"};
    if (om > 59) return {false, "偏移分钟超出 00-59 范围"};
    p.ok = true;
    return p;
}

}  // namespace

/// 扫描一个日期时间词。调用前必须先 looks_like_datetime 命中。
inline scan_out scan(scanner& s) {
    scan_out out;
    const std::size_t begin = s.pos;
    const auto fail_at = [&](const char* why) {
        out.ok = false;
        out.reason = why;
        out.raw = s.src.substr(begin, s.pos - begin);
        return out;
    };

    // Branch 1: bare time (hh:...) — no offset may follow
    if (const auto digit_at = [&](std::size_t i) {
            const char c = s.peek_at(i);
            return c >= '0' && c <= '9';
        };
        digit_at(0) && digit_at(1) && s.peek_at(2) == ':') {
        if (const pieces p = take_time(s); !p.ok) return fail_at(p.reason);
        if (const char z = s.peek(); z == 'Z' || z == 'z' || z == '+' || z == '-') {
            return fail_at("本地时间不能带时区偏移");
        }
        out.ok = true;
        out.raw = s.src.substr(begin, s.pos - begin);
        return out;
    }

    // Branch 2: full-date ...
    int year = 0, month = 0, day = 0;
    for (int i = 0; i < 4; ++i) {
        const char c = s.peek();
        if (c < '0' || c > '9') return fail_at("年份不是 4 位数字");
        year = year * 10 + (c - '0');
        s.bump();
    }
    if (s.peek() != '-') return fail_at("年份后缺少 '-'");
    s.bump();
    if (!take2(s, month)) return fail_at("月份须为两位数字");
    if (month == 0) return fail_at("月份不能用 00");
    if (month > 12) return fail_at("月份超出 01-12 范围");
    if (s.peek() != '-') return fail_at("月份后缺少 '-'");
    s.bump();
    if (!take2(s, day)) return fail_at("日期须为两位数字");
    if (day == 0) return fail_at("日期不能用 00");
    if (day > days_in_month(year, month)) return fail_at("日期超出当月最大天数（含闰年规则）");

    // After the date: a local date stops here, or continue as a full datetime
    const char sep = s.peek();
    const auto digit_c = [](char c) { return c >= '0' && c <= '9'; };
    const bool time_follows = sep == 'T' || sep == 't' ||
                              (sep == ' ' && digit_c(s.peek_at(1)));
    if (!time_follows) {
        out.ok = true;  // local date; trailing space/comment is handled by
                        // expect_line_end
        out.raw = s.src.substr(begin, s.pos - begin);
        return out;
    }
    s.bump();  // T / t / single space
    if (const pieces p = take_time(s); !p.ok) return fail_at(p.reason);
    if (const char z = s.peek(); z == 'Z' || z == 'z' || z == '+' || z == '-') {
        if (const pieces p = take_offset(s); !p.ok) return fail_at(p.reason);
    }
    out.ok = true;
    out.raw = s.src.substr(begin, s.pos - begin);
    return out;
}

}  // namespace cpptoml::detail::rfc

// ===== lib/detail/strnum.hpp =====
// lib/detail/strnum.hpp — leaf token scanning: string / integer / float /
// bool / datetime.
//
// Private header: included by parser.cpp only. Arrays and inline tables are
// document structure (parser.cpp recurses over them); this file handles the
// complete consumption of a single value token and the construction of its
// typed value. Every failure goes through fail() as a parse_abort.
namespace cpptoml::detail::strnum {

// ---- Shared character predicates --------------------------------------------

/// End of a value token: whitespace, a newline, EOF, or a comment start.
inline bool at_delimiter(const scanner& s) {
    return s.eof() || charset::is_ws(s.peek()) || s.at_newline() || s.peek() == '#';
}

// ---- UTF-8 output ------------------------------------------------------------

inline void append_utf8(std::string& out, std::uint32_t cp) {
    if (cp <= 0x7F) {
        out.push_back(static_cast<char>(cp));
    } else if (cp <= 0x7FF) {
        out.push_back(static_cast<char>(0xC0 | (cp >> 6)));
        out.push_back(static_cast<char>(0x80 | (cp & 0x3F)));
    } else if (cp <= 0xFFFF) {
        out.push_back(static_cast<char>(0xE0 | (cp >> 12)));
        out.push_back(static_cast<char>(0x80 | ((cp >> 6) & 0x3F)));
        out.push_back(static_cast<char>(0x80 | (cp & 0x3F)));
    } else {
        out.push_back(static_cast<char>(0xF0 | (cp >> 18)));
        out.push_back(static_cast<char>(0x80 | ((cp >> 12) & 0x3F)));
        out.push_back(static_cast<char>(0x80 | ((cp >> 6) & 0x3F)));
        out.push_back(static_cast<char>(0x80 | (cp & 0x3F)));
    }
}

/// Read n hex digits; too few, invalid, or a surrogate is an error.
inline std::uint32_t take_hex_escape(scanner& s, int n) {
    std::uint32_t cp = 0;
    for (int i = 0; i < n; ++i) {
        if (s.eof() || !charset::is_hex_digit(s.peek())) {
            fail(s, "\\u 转义需要 " + std::to_string(n) + " 位十六进制数字");
        }
        cp = cp * 16 + static_cast<std::uint32_t>(charset::hex_value(s.peek()));
        s.bump();
    }
    if (cp >= 0xD800 && cp <= 0xDFFF) {
        fail(s, "\\u 转义码点是代理区字符（非法）");
    }
    if (cp > 0x10FFFF) {
        fail(s, "十六进制转义码点超出 Unicode 范围");
    }
    return cp;
}

// ---- Escapes -----------------------------------------------------------------

/// Handle the escape after a backslash and return the expanded bytes; s
/// rests on the backslash.
inline std::string take_escape(scanner& s) {
    s.bump();  // backslash
    if (s.eof()) fail(s, "字符串未闭合（转义在文件末尾）");
    const char c = s.peek();
    switch (c) {
        case 'b': s.bump(); return std::string(1, '\b');
        case 't': s.bump(); return std::string(1, '\t');
        case 'n': s.bump(); return std::string(1, '\n');
        case 'f': s.bump(); return std::string(1, '\f');
        case 'r': s.bump(); return std::string(1, '\r');
        case '"': s.bump(); return std::string(1, '"');
        case '\\': s.bump(); return std::string(1, '\\');
        case 'u': s.bump(); break;
        case 'U': s.bump(); break;
        default:
            fail(s, std::string("非法转义 '\\") + c + "'");
    }
    const int n = (c == 'u') ? 4 : 8;
    const std::uint32_t cp = take_hex_escape(s, n);
    std::string out;
    append_utf8(out, cp);
    return out;
}

// ---- Single-line strings -----------------------------------------------------

/// Single-line basic string: s rests on the opening quote; no LF inside,
/// full escapes (\b\t\n\f\r\"\\ \u \U).
inline std::string scan_basic_string(scanner& s) {
    s.bump();  // opening quote
    std::string out;
    for (;;) {
        if (s.eof() || s.peek() == '\n') fail(s, "字符串未闭合（直到行尾没有收引号）");
        if (s.peek() == '"') { s.bump(); return out; }
        if (s.peek() == '\\') {
            out += take_escape(s);
            continue;
        }
        out.push_back(s.peek());
        s.bump();
    }
}

/// Single-line literal string: s rests on the opening quote; no escapes,
/// backslashes stay verbatim.
inline std::string scan_literal_string(scanner& s) {
    s.bump();  // opening quote
    std::string out;
    for (;;) {
        if (s.eof() || s.peek() == '\n') fail(s, "字符串未闭合（直到行尾没有收引号）");
        if (s.peek() == '\'') { s.bump(); return out; }
        out.push_back(s.peek());
        s.bump();
    }
}

// ---- Multiline strings -------------------------------------------------------

/// Multiline string: s rests on the opening triple-quote. basic selects the
/// escaped form; false selects the escape-free literal form.
inline std::string scan_multiline_string(scanner& s, bool basic) {
    const char q = basic ? '"' : '\'';
    s.bump_n(3);  // opening triple-quote

    std::string out;
    // A newline right after the opener is trimmed (only if truly present).
    if (s.at_newline()) s.bump_newline();

    for (;;) {
        if (s.eof()) fail(s, "字符串未闭合（多行串未找到收三连引号）");
        const char c = s.peek();

        // Closing-quote run: k-3 go into the content + 3 close the string;
        // k > 5 is unrepresentable.
        if (c == q) {
            const std::size_t k = s.run_length(q);
            if (k >= 3) {
                if (k > 5) fail(s, "字符串里收引号连串过长（最多 5 个）");
                s.bump_n(k - 3);
                s.bump_n(3);
                return out;
            }
            out.append(k, q);
            s.bump_n(k);
            continue;
        }

        if (basic && c == '\\') {
            // Line-ending backslash: only whitespace may follow \ and a
            // newline must be reached; all whitespace/newlines are then
            // swallowed in one go.
            std::size_t j = 1;
            while (s.peek_at(j) == ' ' || s.peek_at(j) == '\t') ++j;
            const char after = s.peek_at(j);
            if ((after == '\n') || (after == '\r' && s.peek_at(j + 1) == '\n')) {
                s.bump_n(j + 1);       // backslash + spaces + first newline byte
                if (s.peek() == '\n') s.bump();  // LF of the CRLF
                while (!s.eof() && (charset::is_ws(s.peek()) || s.at_newline())) {
                    if (s.at_newline()) s.bump_newline();
                    else s.bump();
                }
                continue;
            }
            out += take_escape(s);
            continue;
        }

        if (c == '\r') { s.bump(); continue; }  // CR of a CRLF: emit LF only
        if (c == '\n') { out.push_back('\n'); s.bump(); continue; }

        out.push_back(c);
        s.bump();
    }
}

// ---- Bools --------------------------------------------------------------------

inline bool scan_bool(scanner& s) {
    const std::string_view word = (s.peek() == 't') ? "true" : "false";
    for (const char w : word) {
        if (s.eof() || s.peek() != w) fail(s, "无法识别的值（true/false 需小写）");
        s.bump();
    }
    return word == "true";
}

// ---- Datetime -----------------------------------------------------------------

/// Scans the datetime token after the look-ahead hit; raw keeps the whole
/// span as written (stored verbatim in the datetime value).
inline cpptoml::datetime scan_datetime(scanner& s) {
    const std::size_t begin_line = s.line;
    const std::size_t begin_col = s.col;
    const rfc::scan_out r = rfc::scan(s);
    if (!r.ok) {
        fail_at(begin_line, begin_col,
                std::string("不是合法的日期时间：") + r.reason);
    }
    return cpptoml::datetime{r.raw};
}

// ---- Integers (radix prefixes) --------------------------------------------------

// ---- Floats ---------------------------------------------------------------------

namespace {

[[noreturn]] void not_float(scanner& s, const char* reason) {
    fail(s, std::string("不是合法的浮点数：") + reason);
}

/// Inside a number, both sides of an underscore must be digits of the
/// current class (the cursor sits on the underscore right now).
inline void check_underscore_neighbors(const scanner& s, char prev, char next, bool (*ok)(char)) {
    if (!ok(prev) || !ok(next)) fail(s, "下划线必须紧邻数字两侧");
}

bool dec_ok(char c) { return c >= '0' && c <= '9'; }

}  // namespace

// ---- Main body ---------------------------------------------------------------------

/// Scans a numeric token: integer / float / inf / nan (with an optional
/// +/- prefix).
/// The caller guarantees the cursor is on a digit, '+' or '-', and that the
/// datetime look-ahead did not hit (looks_like_datetime ruled that out).
inline cpptoml::value scan_number(scanner& s) {
    const std::size_t begin_line = s.line, begin_col = s.col;
    bool negative = false;
    bool has_sign = false;  // radix integers take no sign at all (not even +)
    if (s.peek() == '+' || s.peek() == '-') {
        negative = s.peek() == '-';
        has_sign = true;
        s.bump();
    }

    // inf / nan
    if (s.peek() == 'i' || s.peek() == 'n') {
        std::string_view word = (s.peek() == 'i') ? "inf" : "nan";
        for (const char w : word) {
            if (s.eof() || s.peek() != w) {
                fail_at(begin_line, begin_col, "不是合法的浮点数：inf/nan 未写全");
            }
            s.bump();
        }
        const double v = (word == "inf")
            ? (negative ? -std::numeric_limits<double>::infinity()
                        : std::numeric_limits<double>::infinity())
            : (negative ? -std::numeric_limits<double>::quiet_NaN()
                        : std::numeric_limits<double>::quiet_NaN());
        return v;
    }

    // 0x / 0o / 0b: radix integers never carry a sign
    if (s.peek() == '0' && !s.eof()) {
        const char p = s.peek_at(1);
        if (p == 'x' || p == 'o' || p == 'b') {
            if (has_sign) {
                fail_at(begin_line, begin_col, "进制整数（0x/0o/0b）不允许正负号");
            }
            const int base = (p == 'x') ? 16 : (p == 'o') ? 8 : 2;
            s.bump_n(2);
            std::uint64_t acc = 0;
            bool any = false;
            for (;;) {
                if (!s.eof() && charset::is_radix_digit(s.peek(), base)) {
                    const unsigned d = charset::radix_value(s.peek(), base);
                    if (acc > (UINT64_MAX - d) / static_cast<unsigned>(base)) {
                        fail_at(begin_line, begin_col, "整数超出 64 位表示范围");
                    }
                    acc = acc * static_cast<unsigned>(base) + d;
                    s.bump();
                    any = true;
                } else if (!s.eof() && s.peek() == '_') {
                    if (!any) fail_at(begin_line, begin_col, "下划线必须紧邻数字两侧");
                    s.bump();
                    if (s.eof() || !charset::is_radix_digit(s.peek(), base)) {
                        fail_at(begin_line, begin_col, "下划线必须紧邻数字两侧");
                    }
                } else {
                    break;
                }
            }
            if (!any) fail_at(begin_line, begin_col, "不是合法的整数：前缀后没有数字");
            return static_cast<std::int64_t>(acc);
        }
    }

    // decimal: optional sign + integer part
    if (s.eof() || !dec_ok(s.peek())) {
        fail_at(begin_line, begin_col, negative ? "不是合法的数字：符号后没有数字"
                                                : "不是合法的数字");
    }
    std::string digits;
    {
        const char first = s.peek();
        s.bump();
        if (first == '0') {
            if (!s.eof() && (dec_ok(s.peek()) || s.peek() == '_')) {
                fail_at(begin_line, begin_col, "前导零（十进制整数不能以 0 连数字开头）");
            }
            digits.push_back('0');
        } else {
            digits.push_back(first);
            while (!s.eof()) {
                const char c = s.peek();
                if (dec_ok(c)) { digits.push_back(c); s.bump(); }
                else if (c == '_') {
                    check_underscore_neighbors(s, digits.back(), s.peek_at(1), dec_ok);
                    s.bump();
                } else break;
            }
        }
    }

    // fraction / exponent
    bool is_float = false;
    if (!s.eof() && s.peek() == '.') {
        is_float = true;
        s.bump();
        if (s.eof() || !dec_ok(s.peek())) not_float(s, "小数点后必须有数字");
        digits.push_back('.');
        while (!s.eof()) {
            const char c = s.peek();
            if (dec_ok(c)) { digits.push_back(c); s.bump(); }
            else if (c == '_') { check_underscore_neighbors(s, digits.back(), s.peek_at(1), dec_ok); s.bump(); }
            else break;
        }
    }
    if (!s.eof() && (s.peek() == 'e' || s.peek() == 'E')) {
        is_float = true;
        digits.push_back(s.peek());
        s.bump();
        if (!s.eof() && (s.peek() == '+' || s.peek() == '-')) {
            digits.push_back(s.peek());
            s.bump();
        }
        if (s.eof() || !dec_ok(s.peek())) not_float(s, "指数后必须有数字");
        while (!s.eof()) {
            const char c = s.peek();
            if (dec_ok(c)) { digits.push_back(c); s.bump(); }
            else if (c == '_') { check_underscore_neighbors(s, digits.back(), s.peek_at(1), dec_ok); s.bump(); }
            else break;
        }
    }

    if (!is_float) {
        // decimal integer: accumulate into uint64 first, then restore the
        // sign and clamp to the int64 range.
        std::uint64_t mag = 0;
        for (const char c : digits) {
            const unsigned d = static_cast<unsigned>(c - '0');
            if (mag > (UINT64_MAX - d) / 10) {
                fail_at(begin_line, begin_col, "整数超出 64 位表示范围");
            }
            mag = mag * 10 + d;
        }
        constexpr std::uint64_t kInt64Max = 9223372036854775807ULL;
        constexpr std::uint64_t kInt64Min = 9223372036854775808ULL;
        if (negative) {
            if (mag > kInt64Min) fail_at(begin_line, begin_col, "整数超出 64 位表示范围");
            if (mag == kInt64Min) return std::numeric_limits<std::int64_t>::min();
            return -static_cast<std::int64_t>(mag);
        }
        if (mag > kInt64Max) fail_at(begin_line, begin_col, "整数超出 64 位表示范围");
        return static_cast<std::int64_t>(mag);
    }
    if (negative) digits.insert(digits.begin(), '-');

    errno = 0;
    char* end = nullptr;
    const double v = std::strtod(digits.c_str(), &end);
    if (end != digits.c_str() + digits.size()) {
        not_float(s, "数字形状异常");
    }
    if (errno == ERANGE) {
        if (std::isinf(v)) fail_at(begin_line, begin_col, "浮点数超出范围（超过 64 位浮点表示）");
        // underflow to 0 is fine (TOML only demands lossless
        // representability; tiny values may degrade to 0)
        return 0.0;
    }
    return v;
}

}  // namespace cpptoml::detail::strnum

// ===== lib/detail/utf8.hpp =====
// lib/detail/utf8.hpp — whole-input UTF-8 and control-byte pre-scan.
//
// One linear pass over the whole input before any parsing starts:
//   * strict UTF-8: rejects overlong encodings, surrogates, out-of-range
//     code points and truncated sequences;
//   * BOM (U+FEFF) is only legal at the very start (parse() strips one
//     leading BOM; any other one is an error);
//   * control bytes in layers: NUL..BS, VT, FF, 0x0E..0x1F and DEL are
//     rejected everywhere; TAB is always allowed; LF is allowed (inside
//     single-line strings the string scanner rejects it separately); CR
//     must appear paired (CRLF), a lone CR is rejected everywhere.
// The lexical and string paths therefore only have to deal with LF and
// paired CR, without repeating control-byte checks at every site.
namespace cpptoml::detail::utf8 {

/// Pre-scan result: passes when ok; otherwise bad holds the offending byte
/// offset (0-based).
struct check_result {
    bool ok;
    std::size_t bad;
};

/// Validate input that has already had its leading BOM stripped.
inline check_result check(std::string_view src) {
    const std::size_t n = src.size();
    for (std::size_t i = 0; i < n;) {
        const unsigned char c = static_cast<unsigned char>(src[i]);
        // ---- Control bytes (00..1F and 7F) ----
        if (c <= 0x1F) {
            if (c == 0x09 || c == '\n') { ++i; continue; }  // TAB and LF allowed
            if (c == '\r') {
                if (i + 1 < n && src[i + 1] == '\n') { i += 2; continue; }  // CRLF
                return {false, i};  // lone CR
            }
            return {false, i};  // NUL..BS/VT/FF/0x0E..1F
        }
        if (c == 0x7F) return {false, i};  // DEL: rejected everywhere
        // ---- UTF-8 multi-byte sequences ----
        if (c < 0x80) { ++i; continue; }
        std::size_t len = 0;
        char32_t cp = 0;
        if (c >= 0xC2 && c <= 0xDF) { len = 2; cp = c & 0x1F; }
        else if (c >= 0xE0 && c <= 0xEF) { len = 3; cp = c & 0x0F; }
        else if (c >= 0xF0 && c <= 0xF4) { len = 4; cp = c & 0x07; }
        else return {false, i};  // C0/C1 (overlong), F5..FF, or a lone
                                 // 0x80..0xBF continuation byte as lead
        if (i + len > n) return {false, i};  // truncated
        // Continuation-byte check + code point assembly
        for (std::size_t k = 1; k < len; ++k) {
            const unsigned char cc = static_cast<unsigned char>(src[i + k]);
            if (cc < 0x80 || cc > 0xBF) return {false, i};
            cp = (cp << 6) | (cc & 0x3F);
        }
        // Overlong: the lead-byte ranges above already rule out most of it;
        // enforce each length's lower bound here as well
        if (len == 2 && cp < 0x80) return {false, i};
        if (len == 3 && cp < 0x800) return {false, i};
        if (len == 4 && cp < 0x10000) return {false, i};
        // Surrogates (ED A0..BF sneaks past the lead-byte range; re-check by
        // code point) and out-of-range
        if (cp >= 0xD800 && cp <= 0xDFFF) return {false, i};
        if (cp > 0x10FFFF) return {false, i};
        // U+FEFF may only appear at the very start (parse() strips one
        // leading BOM; anything left is an error)
        if (cp == 0xFEFF) return {false, i};
        i += len;
    }
    return {true, 0};
}

}  // namespace cpptoml::detail::utf8
